 "content": "def transform(grid):
    # Each horizontal run of 3 or 2 represents one output cell.
    counts = {3: 0, 2: 0}
    for row in grid:
        prev = None
        for value in row:
            if value in counts and value != prev:
                counts[value] += 1
            prev = value
    cells = [3] * counts[3] + [2] * counts[2]
    cells = (cells + [0] * 6)[:6]
    return [cells[:3], cells[3:]]
